  assert.ok(dbSource.includes(".eq('account_id', accountId)") && dbSource.includes(".eq('month', month)") && dbSource.includes(".eq('user_id', user.id)"), 'monthly snapshot deletion must stay scoped to the current user, exact account, and exact month');
